// Generated by Automated Quality Gate; review before merging.
const {test} = require('node:test');
const assert = require('./assert.cjs');
const {setup} = require('./harness.cjs');

test('Controller adds task and resets input field', () => {
  const env = setup();
  const vm = env.controller('TaskController');
  vm.title = 'Test task';
  vm.add();
  assert.equal(vm.tasks.length, 1);
  assert.equal(vm.tasks[0].title, 'Test task');
  assert.equal(vm.title, '');
  assert.equal(vm.error, '');
});

test('Controller handles invalid add and shows error', () => {
  const env = setup();
  const vm = env.controller('TaskController');
  vm.title = '';
  vm.add();
  assert.ok(vm.error.length > 0);
  assert.equal(vm.tasks.length, 0);
});

test('Controller remove updates state and clears errors', () => {
  const env = setup();
  const vm = env.controller('TaskController');
  const task = {id: '123', title: 'Task', done: false};
  vm.tasks = [task];
  vm.error = 'Some old error';
  vm.remove('123');
  assert.equal(vm.tasks.length, 0);
  assert.equal(vm.error, '');
});

test('Service handles storage failure gracefully in toggle', () => {
  const env = setup();
  const vm = env.controller('TaskController');
  const task = {id: '456', title: 'Persistence Test', done: false};
  vm.tasks = [task];
  env.failStorageWrites();
  vm.toggle(task);
  assert.equal(task.done, false);
  assert.ok(vm.error.includes('บันทึกไม่ได้'));
});

test('Template binding reflects controller state correctly', () => {
  const env = setup();
  const html = env.readPage('index.html');
  env.dom.window.document.body.innerHTML = html;
  env.injector.invoke(['$compile', '$rootScope', ($compile, $rootScope) => {
    const scope = $rootScope.$new();
    const element = $compile(env.dom.window.document.body)(scope);
    scope.$apply();
    const header = element[0].querySelector('h1');
    assert.equal(header.textContent, 'รายการงานของทีม');
  }]);
});

test('Persistence and loading data across Service cycle', () => {
  const env = setup();
  const service = env.get('TaskService');
  const tasks = service.add([], 'Task A');
  const restored = service.list();
  assert.deepEqual(restored, tasks);
  assert.equal(restored[0].title, 'Task A');
});